import{_ as a,o as i,c as n,ag as t}from"./chunks/framework.BZohXCq9.js";const c=JSON.parse('{"title":"RK3588 与 PX4 飞控高精度时间同步","description":"","frontmatter":{"title":"RK3588 与 PX4 飞控高精度时间同步","tags":["ROS","PX4","时间同步","RK3588","1PPS"],"date":"2026/02/12"},"headers":[],"relativePath":"uav/timesync-time-sync-node.md","filePath":"uav/timesync-time-sync-node.md","lastUpdated":1784519165000}'),e={name:"uav/timesync-time-sync-node.md"};function p(l,s,h,d,r,k){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="rk3588-与-px4-高精度时间同步" tabindex="-1">RK3588 与 PX4 高精度时间同步 <a class="header-anchor" href="#rk3588-与-px4-高精度时间同步" aria-label="Permalink to &quot;RK3588 与 PX4 高精度时间同步&quot;">​</a></h1><p>做无人机多传感器融合，时间同步精度直接影响定位结果。PX4 飞控跑在 STM32 上，机载计算机跑在 RK3588 上，两边各有各的时钟，需要把它们对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PX4 发出的 IMU 数据带的是飞控 boot 时间，RK3588 上的 ROS 用的是系统 CLOCK_MONOTONIC。同一个物理事件，两边的时钟差了几百万微秒。不解决这个问题，VIO、SLAM 全白搭。</p><h2 id="设计思路" tabindex="-1">设计思路 <a class="header-anchor" href="#设计思路" aria-label="Permalink to &quot;设计思路&quot;">​</a></h2><p>核心就一句话：<strong>RK3588时间 = PX4时间 + offset</strong>，关键是 offset 怎么算。</p><p>PX4 每秒输出一个 PPS 脉冲（1Hz），同时通过串口发 TIMESYNC 消息，里面带着 PPS 发生时刻的时间戳 <code>tc1</code>。RK3588 用 GPIO 捕获 PPS 上升沿，拿到本地时间戳。两边一减就是 offset。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PX4                          RK3588</span></span>
<span class="line"><span>│                            │</span></span>
<span class="line"><span>├── PPS 上升沿               │</span></span>
<span class="line"><span>│  tc1 = 1000000 us          │ GPIO 捕获</span></span>
<span class="line"><span>│                            │ = 1234567890 ns</span></span>
<span class="line"><span>│                            │</span></span>
<span class="line"><span>│  offset = 1234567890 - 1000000000 = 234567890 ns</span></span></code></pre></div><p>有了 offset，后续收到 IMU 数据直接加 offset 就行了。</p><h2 id="为什么串口延迟不影响" tabindex="-1">为什么串口延迟不影响 <a class="header-anchor" href="#为什么串口延迟不影响" aria-label="Permalink to &quot;为什么串口延迟不影响&quot;">​</a></h2><p>TIMESYNC 消息里的 <code>tc1</code> 是 PX4 <strong>发出 PPS 的时刻</strong>，不是发出消息的时刻。即使串口有 1ms 延迟，tc1 记录的还是 PPS 那一瞬间的时间，offset 计算基于的是同一个硬件事件。</p><h2 id="offset-平滑" tabindex="-1">offset 平滑 <a class="header-anchor" href="#offset-平滑" aria-label="Permalink to &quot;offset 平滑&quot;">​</a></h2><p>原始 offset 每次算出来都会抖动（GPIO 中断延迟、晶振偏差等），用 EMA 滤波：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (pps_count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (raw_offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> offset) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 快速收敛</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (raw_offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offset) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 稳定跟踪</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>前 10 个 PPS 脉冲用大权重快速拉上去，之后切换到小权重平滑跟踪。</p><h2 id="硬件连接" tabindex="-1">硬件连接 <a class="header-anchor" href="#硬件连接" aria-label="Permalink to &quot;硬件连接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>PX4</th><th>RK3588</th><th>说明</th></tr></thead><tbody><tr><td>PPS</td><td>GPIO 输出</td><td>GPIO3_C6</td><td>1Hz 脉冲</td></tr><tr><td>UART TX</td><td>UART TX</td><td>UART RX</td><td>MAVLink</td></tr><tr><td>UART RX</td><td>UART RX</td><td>UART TX</td><td>MAVLink</td></tr><tr><td>GND</td><td>GND</td><td>GND</td><td>共地</td></tr></tbody></table><h2 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PX4 (STM32H7) ──┬── PPS (1Hz) ──▶ RK3588 GPIO3_C6</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>               └── UART ────────▶ /dev/ttyS9</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>                         timesync_node</span></span>
<span class="line"><span>                         ├── PpsCapture (GPIO 中断捕获)</span></span>
<span class="line"><span>                         ├── MavlinkReceiver (串口解析)</span></span>
<span class="line"><span>                         ├── TimeSynchronizer (offset 计算 + 滤波)</span></span>
<span class="line"><span>                         └── ROS Topics (发布时间戳对齐的 IMU 数据)</span></span></code></pre></div><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h2><p>完整代码在 GitHub 上，基于 ROS Noetic，主要模块：</p><ul><li><strong>PpsCapture</strong> — 用 libgpiod 捕获 GPIO 上升沿，纳秒精度</li><li><strong>MavlinkReceiver</strong> — 串口解析 TIMESYNC 和 RAW_IMU 消息</li><li><strong>TimeSynchronizer</strong> — offset 计算和 EMA 滤波</li><li><strong>TimeSyncNode</strong> — ROS 主节点，串起来发布数据</li></ul><p>编译运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/ros_ws</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catkin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timesync</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timesync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timesync.launch</span></span></code></pre></div>`,24)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
